/* ---------- six things people get wrong ---------- */
FG.myths = [
  {claim:"Consensus, consent and unanimity are the same thing.", fix:"Unanimity means everyone agrees. Consensus means everyone can support the decision. Consent means no one has a reasoned objection. They ask different questions and suit different decisions.", school:"A principal announces “we have consensus” after hearing no objections in a ten-minute slot at the end of a staff meeting. That was, at best, lazy consensus.", refs:["resnick2014","rau2018"], links:["unanimity","consensus_discussion","consent"]},
  {claim:"The voters chose the winner.", fix:"With three or more options, the counting rule can decide the winner. The same ballots can produce different winners under plurality, run-off, ranked or pairwise counting.", school:"In a student council election with three candidates, the candidate with the most first choices can lose to the one most students rank second.", refs:["arrow1951"], links:["voting_rules","majority"]},
  {claim:"Talking always makes groups smarter, or always makes them dumber.", fix:"It depends on the network. When one person sits at the centre, discussion pulls the group toward their view. When people are evenly connected, discussion tends to improve accuracy.", school:"Two schools forecast exam results. The one where every view passes through the deputy head does worse than the one where grade teams talk to each other.", refs:["becker2017","lorenz2011"], links:["network_shape"]},
  {claim:"Open to all means decided by all.", fix:"Groups with no agreed rules hand power to whoever is best connected (Freeman, 1972). Open meetings favour people with time to attend, and weighted votes favour whoever holds the most weight.", school:"The parent association meets at 3 pm. Its decisions reflect parents who can attend at 3 pm.", refs:["freeman1972"], links:["no_structure","majority","dao_token"]},
  {claim:"Random selection is unserious.", fix:"Athens filled most of its public offices by lottery (Hansen, 1991). Ireland used a randomly selected assembly to move an issue that had been stuck for decades.", school:"Drawing parent representatives by lottery can bring in families who would never stand for election.", refs:["hansen1991","farrell2019"], links:["citizens_assembly","kleroterion"]}
];

